    { k: 'rexue', n: '热血' }, { k: 'chunai', n: '纯爱' }, { k: 'xitong', n: '系统' },
    { k: 'zhongsheng', n: '重生' }, { k: 'maoxian', n: '冒险' }, { k: 'lingyi', n: '灵异' },
    { k: 'lianai', n: '恋爱' }, { k: 'xuanhuan', n: '玄幻' }, { k: 'kehuan', n: '科幻' },
