function catName(k) {
    for (var i = 0; i < CATS.length; i++) if (CATS[i].k === k) return CATS[i].n;
    return k;
}

function norm(s) {
    s = String(s == null ? '' : s);
    s = s.replace(/<[^>]+>/g, ' ');
    s = s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
