var PREFIX1 = 'J7r', SUFFIX1 = 'nQ', PREFIX2 = 'kD', SUFFIX2 = 'W4s', BLOCKSIZE = 7;
var CUSTOM_ALPHA = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

// 自定字母表 base64 → 字节 → UTF-8 字符串（海阔没有 atob，java.util.Base64 又要 API26+，手写最稳）
function b64decode(s) {
    var bytes = [], acc = 0, bits = 0, i, v;
    for (i = 0; i < s.length; i++) {
        v = CUSTOM_ALPHA.indexOf(s.charAt(i));
        if (v < 0) continue;
        acc = ((acc << 6) | v) & 0xFFFFFF;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            bytes.push((acc >> bits) & 0xFF);
        }
    }
    var out = '', j = 0;
    while (j < bytes.length) {
        var c = bytes[j++];
        if (c < 0x80) out += String.fromCharCode(c);
        else if (c >= 0xC0 && c < 0xE0) out += String.fromCharCode(((c & 0x1F) << 6) | (bytes[j++] & 0x3F));
        else if (c >= 0xE0 && c < 0xF0) out += String.fromCharCode(((c & 0x0F) << 12) | ((bytes[j++] & 0x3F) << 6) | (bytes[j++] & 0x3F));
        else {
            var cp = ((c & 0x07) << 18) | ((bytes[j++] & 0x3F) << 12) | ((bytes[j++] & 0x3F) << 6) | (bytes[j++] & 0x3F);
            cp -= 0x10000;
            out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
        }
    }
    return out;
}

// 7 字符一块，奇数块（0 起）整块反转
function reorder7(s) {
    var out = '', i, blk;
    for (i = 0; i < s.length; i += BLOCKSIZE) {
        blk = s.substring(i, i + BLOCKSIZE);
        if ((i / BLOCKSIZE) % 2 === 1) blk = blk.split('').reverse().join('');
        out += blk;
    }
    return out;
}

// 加密串 → [{order,url},...]；kD 可能出现多次，只有对的能解出合法 JSON
function decodeImages(enc) {
    enc = String(enc || '');
    if (enc.length < 10) return [];
    var inner = enc.substring(PREFIX1.length, enc.length - SUFFIX1.length);
    var w = inner.indexOf(SUFFIX2);
    if (w < 0) return [];
    var lastPart = inner.substring(w + SUFFIX2.length);
    var kds = [], st = 0, p;
    while (true) {
        p = inner.indexOf(PREFIX2, st);
        if (p === -1 || p >= w) break;
        kds.push(p);
        st = p + 1;
    }
    for (var k = 0; k < kds.length; k++) {
        var kd = kds[k];
        var ri = lastPart + inner.substring(0, kd) + inner.substring(kd + PREFIX2.length, w);
        try {
            var arr = JSON.parse(b64decode(reorder7(ri)));
            if (arr && arr.length) return arr;
        } catch (e) { }
    }
    return [];
}

// 章节表：接口直接给 order，比原 py 用标题正则抠数字靠谱
function getChapters(mid) {
    var j = reqJson(API + '/api/v2/manga/get?mid=' + mid + '&mode=all', 15000);
    if (!j || !j.data || !j.data.chapters) return [];
    var raw = j.data.chapters, out = [];
    for (var i = 0; i < raw.length; i++) {
        var ch = raw[i] || {}, at = ch.attributes || {};
        out.push({
            id: String(ch.id),
            name: norm(at.title || ('第' + ch.id + '话')),
            order: parseFloat(at.order) || (i + 1)
        });
    }
    out.sort(function (a, b) { return a.order - b.order; });
    return out;
}

// 一话的图片地址：接口给加密串 + line，解密后按 line 选 CDN
function getImages(mid, cid) {
    // 取图接口是全站最慢的一个（实测经常 20 秒以上），单独放宽到 18 秒
    var j = reqJson(API + '/api/v2/chapter/getinfo?m=' + mid + '&c=' + cid, 18000);
    if (!j || !j.data || !j.data.info) return [];
    var im = j.data.info.images || {};
    var list = decodeImages(im.images);
    if (!list.length) return [];
    var host = IMG_HOST[String(im.line || '3')] || IMG_HOST['3'];
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var it = list[i], path = '';
        if (typeof it === 'string') path = it;
        else if (it && it.url) path = it.url;
        if (!path) continue;
        if (/^https?:\/\//i.test(path)) out.push(path);
        else if (path.charAt(0) === '/') out.push(host + path);
        else out.push(host + '/' + path);
    }
    return out;
}
